function Value({ icon: Icon, title, body }: { icon: IconType; title: string; body: string }) { return <div className="flex gap-4"><span className="grid size-10 shrink-0 place-items-center rounded-xl bg-secondary text-secondary-foreground"><Icon className="size-5" /></span><div><h3 className="font-extrabold">{title}</h3><p className="mt-1 text-sm leading-6 text-muted-foreground">{body}</p></div></div>; }

function AuthPage({ mode }: { mode: "signin" | "signup" }) {
  const [, setLocation] = useLocation();
  const [email, setEmail] = useState(""); const [password, setPassword] = useState(""); const [name, setName] = useState(""); const [submitted, setSubmitted] = useState(false);
  const createProfile = useCreateCurrentUserProfile();
  const submit = (event: FormEvent) => { event.preventDefault(); setSubmitted(true); if (mode === "signup") createProfile.mutate({ data: { name: name || "Campus rider", email, role: "PASSENGER" } }); setTimeout(() => setLocation("/dashboard"), 450); };
  return <div className="rf-grid flex min-h-[100dvh] items-center justify-center bg-background px-5 py-10"><div className="grid w-full max-w-[980px] overflow-hidden rounded-[2rem] border border-border bg-card shadow-[0_24px_80px_hsl(214_53%_29%/.12)] md:grid-cols-[.85fr_1.15fr]"><div className="hidden bg-primary p-10 text-primary-foreground md:flex md:flex-col"><Logo dark /><div className="mt-auto"><span className="grid size-12 place-items-center rounded-2xl bg-secondary text-secondary-foreground"><Navigation className="size-6 -rotate-12" /></span><h1 className="mt-6 text-4xl font-extrabold leading-tight tracking-[-.06em]">Move with the people who get campus.</h1><p className="mt-4 max-w-xs text-sm leading-6 text-primary-foreground/60">One account for your rides, your route, and your community.</p></div><p className="mt-16 text-[11px] text-primary-foreground/40">RideFlow / Westbridge</p></div><div className="p-7 sm:p-12"><div className="flex items-center justify-between"><Logo /><Link href="/" className="text-xs font-bold text-muted-foreground hover:text-foreground" data-testid="link-auth-home">Back home</Link></div><div className="mx-auto mt-12 max-w-sm"><p className="text-xs font-extrabold uppercase tracking-[.17em] text-accent">{mode === "signin" ? "Welcome back" : "Start here"}</p><h2 className="mt-3 text-3xl font-extrabold tracking-[-.05em] text-primary">{mode === "signin" ? "Good to see you." : "Your next ride starts here."}</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">{mode === "signin" ? "Sign in to see what is moving on campus." : "Create a RideFlow account with your campus email."}</p><form onSubmit={submit} className="mt-8 space-y-4">{mode === "signup" && <label className="block text-xs font-bold">Full name<input value={name} onChange={(e) => setName(e.target.value)} className="mt-2 h-12 w-full rounded-xl border border-input bg-background px-4 text-sm outline-none ring-secondary transition focus:ring-2" placeholder="Maya Chen" required data-testid="input-name" /></label>}<label className="block text-xs font-bold">Campus email<input type="email" value={email} onChange={(e) => setEmail(e.target.value)} className="mt-2 h-12 w-full rounded-xl border border-input bg-background px-4 text-sm outline-none ring-secondary transition focus:ring-2" placeholder="you@westbridge.edu" required data-testid="input-email" /></label><label className="block text-xs font-bold">Password<input type="password" value={password} onChange={(e) => setPassword(e.target.value)} className="mt-2 h-12 w-full rounded-xl border border-input bg-background px-4 text-sm outline-none ring-secondary transition focus:ring-2" placeholder="At least 8 characters" required minLength={8} data-testid="input-password" /></label><Button type="submit" className="mt-2 w-full" disabled={submitted || createProfile.isPending} testId="button-auth-submit">{submitted ? <><Check className="size-4" /> You are in</> : mode === "signin" ? <><LogIn className="size-4" /> Sign in</> : <><ArrowRight className="size-4" /> Create account</>}</Button></form><div className="my-6 flex items-center gap-3 text-[11px] text-muted-foreground"><span className="h-px flex-1 bg-border" />or<span className="h-px flex-1 bg-border" /></div><Button variant="secondary" className="w-full" onClick={() => setLocation("/dashboard")} testId="button-campus-sso"><ShieldCheck className="size-4" /> Continue with campus SSO</Button><p className="mt-7 text-center text-xs text-muted-foreground">{mode === "signin" ? "New to RideFlow? " : "Already have an account? "}<Link href={mode === "signin" ? "/sign-up" : "/sign-in"} className="font-bold text-accent hover:underline" data-testid="link-switch-auth">{mode === "signin" ? "Create an account" : "Sign in instead"}</Link></p></div></div></div></div>;
}

function PageHeading({ eyebrow, title, body, action }: { eyebrow?: string; title: string; body?: string; action?: ReactNode }) {
  return <div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="text-[11px] font-extrabold uppercase tracking-[.18em] text-accent">{eyebrow ?? "RideFlow"}</p><h1 className="mt-2 text-3xl font-extrabold tracking-[-.055em] text-primary sm:text-4xl">{title}</h1>{body && <p className="mt-2 max-w-xl text-sm leading-6 text-muted-foreground">{body}</p>}</div>{action}</div>;
}

function Metric({ label, value, note, icon: Icon, tone = "primary" }: { label: string; value: string | number; note: string; icon: IconType; tone?: "primary" | "accent" | "yellow" }) {
  return <div className="rounded-2xl border border-border bg-card p-5" data-testid={`metric-${label.toLowerCase().replaceAll(" ", "-")}`}><div className="flex items-start justify-between"><span className="text-[11px] font-bold uppercase tracking-[.12em] text-muted-foreground">{label}</span><span className={`grid size-9 place-items-center rounded-xl ${tone === "yellow" ? "bg-secondary text-secondary-foreground" : tone === "accent" ? "bg-accent/10 text-accent" : "bg-primary/10 text-primary"}`}><Icon className="size-4" /></span></div><p className="mt-5 text-3xl font-extrabold tracking-[-.06em] text-primary">{value}</p><p className="mt-1 text-xs text-muted-foreground">{note}</p></div>;
}

function Dashboard() {
  const { data: user, isLoading: userLoading } = useGetCurrentUser({ query: { queryKey: getGetCurrentUserQueryKey(), retry: false } });
  const ridesQuery = useListRides({ limit: 20 }, { query: { queryKey: getListRidesQueryKey({ limit: 20 }), retry: false } });
  const rides = ridesQuery.data ?? [];
  const active = rides.find((ride) => !["COMPLETED", "CANCELLED", "REJECTED"].includes(ride.status));
  const role = (user?.role as Role | undefined) ?? "PASSENGER";
  if (userLoading) return <AppShell><div className="space-y-6"><Skeleton className="h-10 w-64" /><div className="grid gap-4 md:grid-cols-3"><Skeleton className="h-36" /><Skeleton className="h-36" /><Skeleton className="h-36" /></div></div></AppShell>;
  return <AppShell role={role} userName={user?.name}><PageHeading eyebrow={`${role === "DRIVER" ? "Driver desk" : role === "ADMIN" ? "Operations" : "Tuesday on campus"}`} title={`Good morning${user?.name ? `, ${user.name.split(" ")[0]}` : ""}.`} body={role === "DRIVER" ? "Your next trip is clear. Check your availability and keep moving." : role === "ADMIN" ? "A live read on the people and rides powering Westbridge." : "Where are you headed next?"} action={role === "PASSENGER" ? <Link href="/request-ride" className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-primary px-4 text-sm font-bold text-primary-foreground transition hover:-translate-y-0.5" data-testid="link-dashboard-request"><Plus className="size-4" /> Request a ride</Link> : undefined} /><div className="mt-8 grid gap-4 md:grid-cols-3">{role === "ADMIN" ? <AdminMetrics /> : role === "DRIVER" ? <DriverMetrics /> : <><Metric label="Rides this month" value={rides.filter((r) => r.status === "COMPLETED").length || "—"} note="Keep your campus moving" icon={Navigation} /><Metric label="Avg. wait time" value="4 min" note="Across Westbridge" icon={Clock3} tone="yellow" /><Metric label="Your rating" value={user?.rating ? user.rating.toFixed(1) : "—"} note="Based on recent rides" icon={Star} tone="accent" /></>}</div><div className="mt-7 grid gap-6 lg:grid-cols-[1.2fr_.8fr]"><section className="rounded-2xl border border-border bg-card p-5 sm:p-6"><div className="flex items-center justify-between"><div><h2 className="font-extrabold text-primary">Your active ride</h2><p className="mt-1 text-xs text-muted-foreground">The one thing to keep an eye on</p></div><Link href="/rides" className="text-xs font-bold text-accent hover:underline" data-testid="link-view-rides">View all rides</Link></div>{active ? <RideCard ride={active} compact /> : <div className="mt-6"><EmptyState icon={Navigation} title="No active rides" body="Your next trip across campus will show up here." action={role === "PASSENGER" ? <Link href="/request-ride" className="text-xs font-bold text-accent hover:underline" data-testid="link-empty-request">Request a ride</Link> : undefined} /></div>}</section><section className="rounded-2xl bg-primary p-6 text-primary-foreground"><div className="flex items-center justify-between"><p className="text-xs font-bold uppercase tracking-[.13em] text-primary-foreground/55">Campus pulse</p><Activity className="size-4 text-secondary" /></div><p className="mt-10 text-5xl font-extrabold tracking-[-.08em]">12<span className="text-xl text-secondary"> min</span></p><p className="mt-2 text-sm text-primary-foreground/60">Average pickup time right now</p><div className="mt-7 flex items-end gap-1.5"><span className="h-5 w-2 rounded-full bg-secondary/50" /><span className="h-8 w-2 rounded-full bg-secondary/60" /><span className="h-6 w-2 rounded-full bg-secondary/70" /><span className="h-12 w-2 rounded-full bg-secondary" /><span className="h-9 w-2 rounded-full bg-secondary/80" /><span className="h-14 w-2 rounded-full bg-secondary" /><span className="h-10 w-2 rounded-full bg-secondary/80" /><span className="h-16 w-2 rounded-full bg-secondary" /></div><p className="mt-3 text-[11px] text-primary-foreground/45">Last 8 hours · all pickup zones</p></section></div><RecentRides rides={rides.slice(0, 3)} loading={ridesQuery.isLoading} error={ridesQuery.isError} retry={ridesQuery.refetch} /></AppShell>;
}

function AdminMetrics() { const { data } = useGetAdminOverview({ query: { queryKey: getGetAdminOverviewQueryKey(), retry: false } }); return <><Metric label="Rides today" value={data?.ridesToday ?? "—"} note="Across all campus zones" icon={Navigation} /><Metric label="Active drivers" value={data?.activeDrivers ?? "—"} note={`${data?.totalDrivers ?? "—"} total driver profiles`} icon={CarFront} tone="yellow" /><Metric label="Revenue today" value={data ? `$${data.revenueToday.toFixed(2)}` : "—"} note={data ? `${data.averageRating.toFixed(1)} average rating` : "Awaiting live data"} icon={TrendingUp} tone="accent" /></>; }
function DriverMetrics() { const { data } = useGetDriverProfile({ query: { queryKey: getGetDriverProfileQueryKey(), retry: false } }); return <><Metric label="Total trips" value={data?.totalTrips ?? "—"} note="You are part of the flow" icon={Navigation} /><Metric label="Your rating" value={data?.rating ? data.rating.toFixed(1) : "—"} note="Keep the good energy" icon={Star} tone="yellow" /><Metric label="Availability" value={data?.isAvailable ? "Online" : "Offline"} note="Toggle from your driver desk" icon={Activity} tone="accent" /></>; }

function RideCard({ ride, compact = false }: { ride: any; compact?: boolean }) {
  return <div className={`rounded-2xl border border-border bg-card ${compact ? "mt-5 p-4" : "p-5"}`} data-testid={`card-ride-${ride.id}`}><div className="flex items-start justify-between gap-3"><div><StatusPill status={ride.status} /><p className="mt-3 text-sm font-bold">{ride.pickup}</p><div className="my-1 ml-1 h-4 border-l border-dashed border-border" /><p className="text-sm font-bold">{ride.dropoff}</p></div><div className="text-right"><p className="font-mono text-sm font-medium">${(ride.finalFare ?? ride.estimatedFare ?? 0).toFixed(2)}</p><p className="mt-1 text-[11px] text-muted-foreground">{ride.distanceKm?.toFixed?.(1) ?? "—"} km · {ride.durationMinutes ?? "—"} min</p></div></div>{!compact && <div className="mt-5 flex items-center justify-between border-t border-border pt-4 text-xs text-muted-foreground"><span>{ride.driverName ? `Driver ${ride.driverName}` : "Looking for a driver"}</span><span>{ride.requestedAt ? new Date(ride.requestedAt).toLocaleDateString() : "Today"}</span></div>}</div>;
}

function RecentRides({ rides, loading, error, retry }: { rides: any[]; loading: boolean; error: boolean; retry: () => void }) { return <section className="mt-7"><div className="mb-4 flex items-center justify-between"><div><h2 className="font-extrabold text-primary">Recent rides</h2><p className="mt-1 text-xs text-muted-foreground">A quick look at your movement</p></div><Link href="/rides" className="text-xs font-bold text-accent hover:underline" data-testid="link-recent-rides">Ride history</Link></div>{loading ? <div className="grid gap-3 md:grid-cols-3"><Skeleton className="h-44" /><Skeleton className="h-44" /><Skeleton className="h-44" /></div> : error ? <ErrorState compact onRetry={retry} /> : rides.length ? <div className="grid gap-3 md:grid-cols-3">{rides.map((ride) => <RideCard ride={ride} key={ride.id} />)}</div> : <EmptyState title="Your ride history is quiet" body="Once you take your first ride, the details will live here." icon={Navigation} />}</section>; }

function RequestRide() {
  const [, setLocation] = useLocation(); const client = useQueryClient(); const request = useRequestRide(); const [pickup, setPickup] = useState(""); const [dropoff, setDropoff] = useState(""); const [submitted, setSubmitted] = useState(false);
  const coords = { lat: 40.7128, lng: -74.006 }; const nearby = useListNearbyDrivers(coords, { query: { enabled: Boolean(pickup && dropoff), queryKey: getListNearbyDriversQueryKey(coords), retry: false } });
  const estimate = pickup && dropoff ? 7.5 : 0;
  const submit = (event: FormEvent) => { event.preventDefault(); request.mutate({ data: { pickup, dropoff, pickupLat: coords.lat, pickupLng: coords.lng, dropoffLat: coords.lat + .006, dropoffLng: coords.lng + .004 } }, { onSuccess: () => { setSubmitted(true); client.invalidateQueries({ queryKey: getListRidesQueryKey() }); setTimeout(() => setLocation("/rides"), 700); } }); };
  return <AppShell><PageHeading eyebrow="Passenger" title="Where are you headed?" body="Add two campus spots and we will find the best nearby ride." /><div className="mt-8 grid gap-6 lg:grid-cols-[1.1fr_.9fr]"><section className="rounded-2xl border border-border bg-card p-5 sm:p-7"><form onSubmit={submit}><div className="relative space-y-3"><div className="absolute left-[18px] top-10 h-16 border-l border-dashed border-accent/50" /><label className="relative block text-xs font-bold">Pickup<div className="absolute left-3 top-[37px] size-3 rounded-full border-[3px] border-accent bg-card" /><input value={pickup} onChange={(e) => setPickup(e.target.value)} className="mt-2 h-14 w-full rounded-xl border border-input bg-background pl-10 pr-4 text-sm outline-none transition focus:border-accent focus:ring-2 focus:ring-accent/20" placeholder="Residence hall, library, or gate" required data-testid="input-pickup" /></label><label className="relative block text-xs font-bold">Dropoff<div className="absolute left-3 top-[37px] size-3 rounded-full bg-secondary-foreground" /><input value={dropoff} onChange={(e) => setDropoff(e.target.value)} className="mt-2 h-14 w-full rounded-xl border border-input bg-background pl-10 pr-4 text-sm outline-none transition focus:border-accent focus:ring-2 focus:ring-accent/20" placeholder="Where should we take you?" required data-testid="input-dropoff" /></label></div><div className="mt-7 rounded-2xl bg-muted/70 p-4"><div className="flex items-center justify-between"><span className="text-xs font-bold text-muted-foreground">Estimated fare</span><span className="font-mono text-xl font-bold text-primary">{estimate ? `$${estimate.toFixed(2)}` : "—"}</span></div><div className="mt-3 grid grid-cols-2 gap-3 border-t border-border pt-3 text-xs"><span className="text-muted-foreground">Typical wait <strong className="ml-1 text-foreground">4–7 min</strong></span><span className="text-right text-muted-foreground">Typical trip <strong className="ml-1 text-foreground">12 min</strong></span></div></div><Button type="submit" className="mt-5 w-full" disabled={!pickup || !dropoff || request.isPending || submitted} testId="button-request-ride">{request.isPending ? <><Loader2 className="size-4 animate-spin" /> Finding your ride</> : submitted ? <><Check className="size-4" /> Ride requested</> : <><Navigation className="size-4" /> Find a ride</>}</Button>{request.isError && <p className="mt-3 text-center text-xs font-bold text-destructive" data-testid="text-request-error">We could not request that ride. Check your stops and try again.</p>}</form></section><section className="rf-map min-h-[390px] overflow-hidden rounded-2xl p-5"><div className="flex items-center justify-between rounded-xl border border-card/20 bg-sidebar/80 px-4 py-3 text-sidebar-foreground backdrop-blur"><div><p className="text-[10px] font-bold uppercase tracking-[.15em] text-sidebar-foreground/55">Nearby drivers</p><p className="mt-1 text-sm font-bold">{nearby.data?.length ?? 3} in your zone</p></div><span className="grid size-8 place-items-center rounded-lg bg-[#74c69d]/15 text-[#a6e3be]"><Activity className="size-4" /></span></div><div className="mt-44 rounded-xl border border-card/20 bg-sidebar/80 p-4 text-sidebar-foreground backdrop-blur"><div className="flex items-center gap-3"><div className="relative"><Avatar name={nearby.data?.[0]?.name ?? "Ari Lee"} /><span className="absolute -bottom-0.5 -right-0.5 size-3 rounded-full border-2 border-sidebar bg-[#74c69d]" /></div><div><p className="text-sm font-bold">{nearby.data?.[0]?.name ?? "Ari Lee"}</p><p className="text-[11px] text-sidebar-foreground/55">Campus driver · 4.9 rating</p></div><span className="ml-auto text-right"><strong className="block text-sm text-secondary">{nearby.data?.[0]?.etaMinutes ?? 4} min</strong><small className="text-[10px] text-sidebar-foreground/50">away</small></span></div></div></section></div><div className="mt-7 flex items-start gap-3 rounded-2xl border border-accent/20 bg-accent/5 p-4 text-xs text-muted-foreground"><ShieldCheck className="mt-0.5 size-4 shrink-0 text-accent" /><p><strong className="text-foreground">Your safety matters.</strong> RideFlow shares your trip details only with your matched driver and keeps a record of every ride.</p></div></AppShell>;
}

function Rides() {
  const ridesQuery = useListRides({ limit: 50 }, { query: { queryKey: getListRidesQueryKey({ limit: 50 }), retry: false } }); const cancel = useCancelRide(); const client = useQueryClient(); const rides = ridesQuery.data ?? []; const [filter, setFilter] = useState("all"); const shown = filter === "all" ? rides : rides.filter((ride) => ride.status === filter);
  return <AppShell><PageHeading eyebrow="Passenger" title="Your rides" body="Everything you have taken, requested, and completed." action={<Link href="/request-ride" className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-primary px-4 text-sm font-bold text-primary-foreground transition hover:-translate-y-0.5" data-testid="link-rides-request"><Plus className="size-4" /> New ride</Link>} /><div className="mt-8 flex flex-wrap items-center justify-between gap-3"><div className="flex gap-1 rounded-xl bg-muted p-1">{[["all","All rides"],["COMPLETED","Completed"],["CANCELLED","Cancelled"]].map(([value,label]) => <button key={value} onClick={() => setFilter(value)} className={`rounded-lg px-3 py-2 text-xs font-bold transition ${filter === value ? "bg-card text-foreground shadow-sm" : "text-muted-foreground"}`} data-testid={`button-filter-${value.toLowerCase()}`}>{label}</button>)}</div><button className="inline-flex items-center gap-2 text-xs font-bold text-muted-foreground hover:text-foreground" data-testid="button-filter-options"><ListFilter className="size-4" /> Filter options</button></div><div className="mt-5 grid gap-4 lg:grid-cols-2">{ridesQuery.isLoading ? [1,2,3,4].map((n) => <Skeleton key={n} className="h-48" />) : ridesQuery.isError ? <div className="lg:col-span-2"><ErrorState onRetry={ridesQuery.refetch} /></div> : shown.length ? shown.map((ride) => <div key={ride.id}><RideCard ride={ride} />{["REQUESTED","SEARCHING","DRIVER_ASSIGNED","DRIVER_ARRIVING"].includes(ride.status) && <button onClick={() => cancel.mutate({ id: ride.id }, { onSuccess: () => client.invalidateQueries({ queryKey: getListRidesQueryKey() }) })} className="mt-[-52px] mr-5 float-right text-[11px] font-bold text-destructive hover:underline" data-testid={`button-cancel-ride-${ride.id}`}>Cancel ride</button>}</div>) : <div className="lg:col-span-2"><EmptyState icon={Navigation} title={filter === "all" ? "No rides yet" : "Nothing in this filter"} body={filter === "all" ? "Request a ride when you are ready to cross campus." : "Try another view to see more of your trips."} action={filter === "all" ? <Link href="/request-ride" className="text-xs font-bold text-accent" data-testid="link-empty-rides-request">Request a ride</Link> : undefined} /></div>}</div></AppShell>;
}

function Driver() {
  const profile = useGetDriverProfile({ query: { queryKey: getGetDriverProfileQueryKey(), retry: false } }); const update = useUpdateDriverAvailability(); const rides = useListRides({ status: "SEARCHING", limit: 20 }, { query: { queryKey: getListRidesQueryKey({ status: "SEARCHING", limit: 20 }), retry: false } }); const accept = useAcceptRide(); const reject = useRejectRide(); const client = useQueryClient(); const [online, setOnline] = useState(false);
  const toggle = () => update.mutate({ data: { isAvailable: !online, currentLat: 40.7128, currentLng: -74.006 } }, { onSuccess: (data) => { setOnline(data.isAvailable); client.invalidateQueries({ queryKey: getGetDriverProfileQueryKey() }); } });
  const requests = rides.data ?? [];
  return <AppShell role="DRIVER"><PageHeading eyebrow="Driver desk" title="Keep campus moving." body="A clear view of your availability, incoming requests, and current trip." action={<Button variant={online ? "secondary" : "primary"} onClick={toggle} disabled={update.isPending} testId="button-toggle-availability"><span className={`size-2 rounded-full ${online ? "bg-accent" : "bg-current"}`} />{online ? "You are online" : "Go online"}</Button>} /><div className="mt-8 grid gap-5 lg:grid-cols-[.75fr_1.25fr]"><section className="rounded-2xl border border-border bg-card p-6"><div className="flex items-center gap-4"><span className={`grid size-12 place-items-center rounded-2xl ${online ? "bg-accent/10 text-accent" : "bg-muted text-muted-foreground"}`}><CarFront className="size-6" /></span><div><p className="font-extrabold">{profile.data?.vehicleMake ?? "Your vehicle"} {profile.data?.vehicleModel ?? ""}</p><p className="mt-1 text-xs text-muted-foreground">{profile.data?.vehicleColor ?? "Campus"} · {profile.data?.vehiclePlate ?? "plate on file"}</p></div></div><div className="mt-7 border-t border-border pt-5"><p className="text-xs font-bold uppercase tracking-[.13em] text-muted-foreground">Today at a glance</p><div className="mt-4 grid grid-cols-2 gap-3"><div className="rounded-xl bg-muted p-3"><p className="text-2xl font-extrabold text-primary">{profile.data?.totalTrips ?? "—"}</p><p className="mt-1 text-[11px] text-muted-foreground">Total trips</p></div><div className="rounded-xl bg-muted p-3"><p className="text-2xl font-extrabold text-primary">{profile.data?.rating?.toFixed?.(1) ?? "—"}</p><p className="mt-1 text-[11px] text-muted-foreground">Rating</p></div></div></div><div className="mt-5 flex items-start gap-2 text-xs leading-5 text-muted-foreground"><ShieldCheck className="mt-0.5 size-4 shrink-0 text-accent" />Only accept trips you can complete safely and comfortably.</div></section><section className="rounded-2xl border border-border bg-card p-6"><div className="flex items-center justify-between"><div><h2 className="font-extrabold text-primary">Incoming requests</h2><p className="mt-1 text-xs text-muted-foreground">{online ? "New requests will appear as they come in." : "Go online to start receiving requests."}</p></div><span className="rounded-full bg-secondary px-2.5 py-1 text-[11px] font-bold text-secondary-foreground">{requests.length} open</span></div>{rides.isLoading ? <div className="mt-5 space-y-3"><Skeleton className="h-28" /><Skeleton className="h-28" /></div> : requests.length ? <div className="mt-5 space-y-3">{requests.map((ride) => <div key={ride.id} className="rounded-xl border border-border p-4" data-testid={`card-driver-request-${ride.id}`}><div className="flex items-start justify-between"><div><p className="text-sm font-bold">{ride.pickup}</p><p className="my-1 text-[11px] text-muted-foreground">to {ride.dropoff}</p><p className="text-xs text-muted-foreground">{ride.distanceKm?.toFixed?.(1) ?? "—"} km · {ride.durationMinutes ?? "—"} min</p></div><p className="font-mono text-sm font-bold">${(ride.estimatedFare ?? 0).toFixed(2)}</p></div><div className="mt-4 flex gap-2"><Button className="flex-1" onClick={() => accept.mutate({ id: ride.id }, { onSuccess: () => client.invalidateQueries({ queryKey: getListRidesQueryKey() }) })} testId={`button-accept-ride-${ride.id}`}><Check className="size-4" /> Accept</Button><Button variant="ghost" onClick={() => reject.mutate({ id: ride.id }, { onSuccess: () => client.invalidateQueries({ queryKey: getListRidesQueryKey() }) })} testId={`button-reject-ride-${ride.id}`}><X className="size-4" /> Pass</Button></div></div>)}</div> : <div className="mt-5"><EmptyState icon={Bell} title={online ? "You are ready" : "You are offline"} body={online ? "We will bring new trip requests here." : "Switch availability on whenever you are ready to drive."} /></div>}</section></div><section className="mt-6 rounded-2xl border border-border bg-card p-6"><div className="flex items-center justify-between"><div><h2 className="font-extrabold text-primary">Current ride controls</h2><p className="mt-1 text-xs text-muted-foreground">Update your passenger as the ride progresses.</p></div><Clock3 className="size-5 text-muted-foreground" /></div><EmptyState icon={Navigation} title="No ride in progress" body="Accepted rides will show their next safe step here." /></section></AppShell>;
}

function Admin() {
  const overview = useGetAdminOverview({ query: { queryKey: getGetAdminOverviewQueryKey(), retry: false } }); const rides = useListAdminRides({ limit: 20 }, { query: { queryKey: getListAdminRidesQueryKey({ limit: 20 }), retry: false } }); const users = useListAdminUsers({ limit: 20 }, { query: { queryKey: getListAdminUsersQueryKey({ limit: 20 }), retry: false } }); const [tab, setTab] = useState<"overview" | "rides" | "users">("overview");
  const statusCounts = overview.data?.rideStatusCounts ?? {}; const total = Object.values(statusCounts).reduce((sum, count) => sum + count, 0) || 1;
  return <AppShell role="ADMIN"><PageHeading eyebrow="Operations / live network" title="Keep the flow healthy." body="The campus-wide view for the people who keep every ride dependable." action={<Button variant="secondary" onClick={() => { overview.refetch(); rides.refetch(); users.refetch(); }} testId="button-refresh-admin"><RefreshCw className="size-4" /> Refresh data</Button>} /><div className="mt-8 grid gap-4 md:grid-cols-4"><Metric label="Total users" value={overview.data?.totalUsers ?? "—"} note={`${overview.data?.totalPassengers ?? "—"} passengers`} icon={UsersRound} /><Metric label="Rides today" value={overview.data?.ridesToday ?? "—"} note={`${overview.data?.completedRides ?? "—"} completed`} icon={Navigation} tone="yellow" /><Metric label="Active drivers" value={overview.data?.activeDrivers ?? "—"} note={`${overview.data?.totalDrivers ?? "—"} driver profiles`} icon={CarFront} tone="accent" /><Metric label="Avg. rating" value={overview.data?.averageRating?.toFixed?.(1) ?? "—"} note="Across completed trips" icon={Star} /></div><div className="mt-7 flex gap-1 rounded-xl bg-muted p-1 md:w-fit">{[["overview","Overview"],["rides","Live rides"],["users","Users"]].map(([value,label]) => <button key={value} onClick={() => setTab(value as typeof tab)} className={`rounded-lg px-4 py-2.5 text-xs font-bold transition ${tab === value ? "bg-card text-foreground shadow-sm" : "text-muted-foreground"}`} data-testid={`button-admin-tab-${value}`}>{label}</button>)}</div>{tab === "overview" && <div className="mt-5 grid gap-5 lg:grid-cols-[1.05fr_.95fr]"><section className="rounded-2xl border border-border bg-card p-6"><div className="flex items-start justify-between"><div><h2 className="font-extrabold text-primary">Ride status today</h2><p className="mt-1 text-xs text-muted-foreground">A live distribution of network demand</p></div><BarChart3 className="size-5 text-accent" /></div><div className="mt-8 space-y-4">{[["COMPLETED","Completed","bg-accent"],["IN_PROGRESS","In progress","bg-primary"],["DRIVER_ARRIVING","Driver arriving","bg-secondary-foreground"],["SEARCHING","Searching","bg-secondary"]].map(([key,label,color]) => { const count = statusCounts[key] ?? 0; return <div key={key}><div className="flex justify-between text-xs"><span className="font-bold">{label}</span><span className="font-mono text-muted-foreground">{count}</span></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-muted"><div className={`h-full rounded-full ${color}`} style={{ width: `${Math.max(count / total * 100, count ? 4 : 0)}%` }} /></div></div>; })}</div></section><section className="rounded-2xl bg-primary p-6 text-primary-foreground"><div className="flex items-center justify-between"><p className="text-xs font-bold uppercase tracking-[.13em] text-primary-foreground/55">Network note</p><ShieldCheck className="size-5 text-secondary" /></div><h2 className="mt-16 max-w-xs text-3xl font-extrabold leading-tight tracking-[-.05em]">Healthy systems feel invisible.</h2><p className="mt-4 max-w-sm text-sm leading-6 text-primary-foreground/60">Keep an eye on wait times, available drivers, and the moments where a passenger might be left waiting.</p><div className="mt-8 flex items-center gap-2 text-xs font-bold text-secondary"><span className="size-2 rounded-full bg-secondary rf-pulse" /> All campus zones reporting</div></section></div>}{tab === "rides" && <AdminRides rides={rides.data ?? []} loading={rides.isLoading} error={rides.isError} retry={rides.refetch} />}{tab === "users" && <AdminUsers users={users.data ?? []} loading={users.isLoading} error={users.isError} retry={users.refetch} />}</AppShell>;
}

function AdminRides({ rides, loading, error, retry }: { rides: any[]; loading: boolean; error: boolean; retry: () => void }) { if (loading) return <div className="mt-5 space-y-3"><Skeleton className="h-16" /><Skeleton className="h-16" /><Skeleton className="h-16" /></div>; if (error) return <div className="mt-5"><ErrorState onRetry={retry} /></div>; return <div className="mt-5 overflow-hidden rounded-2xl border border-border bg-card"><div className="hidden grid-cols-[1.2fr_1fr_1fr_.6fr] gap-4 border-b border-border bg-muted/60 px-5 py-3 text-[10px] font-bold uppercase tracking-[.13em] text-muted-foreground sm:grid"><span>Route</span><span>Passenger</span><span>Status</span><span className="text-right">Fare</span></div>{rides.length ? rides.map((ride) => <div key={ride.id} className="grid gap-2 border-b border-border px-5 py-4 last:border-0 sm:grid-cols-[1.2fr_1fr_1fr_.6fr] sm:items-center sm:gap-4" data-testid={`row-admin-ride-${ride.id}`}><div><p className="text-sm font-bold">{ride.pickup}</p><p className="text-[11px] text-muted-foreground">to {ride.dropoff}</p></div><span className="text-xs text-muted-foreground">{ride.passengerName}</span><StatusPill status={ride.status} /><span className="font-mono text-xs font-bold sm:text-right">${(ride.finalFare ?? ride.estimatedFare ?? 0).toFixed(2)}</span></div>) : <div className="p-8"><EmptyState icon={Navigation} title="No live rides" body="New campus rides will appear in this operations view." /></div>}</div>; }
function AdminUsers({ users, loading, error, retry }: { users: any[]; loading: boolean; error: boolean; retry: () => void }) { if (loading) return <div className="mt-5 space-y-3"><Skeleton className="h-16" /><Skeleton className="h-16" /><Skeleton className="h-16" /></div>; if (error) return <div className="mt-5"><ErrorState onRetry={retry} /></div>; return <div className="mt-5 overflow-hidden rounded-2xl border border-border bg-card">{users.length ? users.map((user) => <div key={user.id} className="flex items-center gap-3 border-b border-border px-5 py-4 last:border-0" data-testid={`row-admin-user-${user.id}`}><Avatar name={user.name} size="sm" /><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold">{user.name}</p><p className="truncate text-xs text-muted-foreground">{user.email}</p></div><span className="rounded-full bg-muted px-2.5 py-1 text-[10px] font-bold text-muted-foreground">{user.role}</span><span className="hidden text-xs text-muted-foreground sm:block">{user.totalRides} rides</span></div>) : <div className="p-8"><EmptyState icon={UsersRound} title="No users to show" body="Campus accounts will appear here as they join." /></div>}</div>; }

function RouteView() { const [location] = useLocation(); if (location === "/") return <Landing />; return <Switch><Route path="/sign-in/*?" component={() => <AuthPage mode="signin" />} /><Route path="/sign-up/*?" component={() => <AuthPage mode="signup" />} /><Route path="/dashboard" component={Dashboard} /><Route path="/request-ride" component={RequestRide} /><Route path="/rides" component={Rides} /><Route path="/driver" component={Driver} /><Route path="/admin" component={Admin} /><Route component={NotFound} /></Switch>; }
function RoutedErrorBoundary() { const [location] = useLocation(); return <ErrorBoundary resetKey={location}><RouteView /></ErrorBoundary>; }
function App() { return <QueryClientProvider client={queryClient}><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, "")}><RoutedErrorBoundary /></WouterRouter></QueryClientProvider>; }

export default App;